    return this.reportsApplied && (!!this.userFilters.industry || !!this.userFilters.sector || this.isSuperAdmin && !this.isGlobalInstituteActive && !!this.selectedInstituteName || !!this.selectedExam || !!this.selectedTestTitle || !!this.userFilters.campus_id || Array.isArray(this.userFilters.department_id) && this.userFilters.department_id.length > 0 || Array.isArray(this.userFilters.teams_id) && this.userFilters.teams_id.length > 0 || !!this.userFilters.active_status || !!this.userFilters.created_by_me);
